def plot_leiden_community_network(
    comm: dict[str, Any],
    out: Path,
    top_communities: int = 20,
) -> None:
    """Plot the saved Leiden community graph without rerunning analysis."""
    from collections import Counter
    import math
    import networkx as nx
    import matplotlib.pyplot as plt

    leiden = comm.get("leiden", {})
    bridge_results = comm.get("bridges", {})
    community_data = bridge_results.get("communityBridgeMetrics", {})

    membership = leiden.get("membership", {})
    pairs = community_data.get("communityPairs", [])

    if not membership:
        print("[skip] Missing leiden.membership in commMetrics.json")
        return

    if not pairs:
        print("[skip] Missing communityBridgeMetrics.communityPairs")
        return

    # Keep IDs as integers throughout; this avoids string/int mismatches.
    sizes = Counter(int(cid) for cid in membership.values())
    largest_ids = {
        cid for cid, _ in sizes.most_common(top_communities)
    }

    graph = nx.Graph()

    for cid in largest_ids:
        graph.add_node(cid, size=sizes[cid])

    for item in pairs:
        a = int(item["communityA"])
        b = int(item["communityB"])

        if a not in largest_ids or b not in largest_ids:
            continue

        graph.add_edge(
            a,
            b,
            weight=int(item["numEdges"]),
            bridge_count=int(item.get("numBridgeEdges", 0)),
        )

    print(
        f"[community plot] Saved communities: {len(sizes):,}; "
        f"saved community pairs: {len(pairs):,}; "
        f"plot nodes: {graph.number_of_nodes():,}; "
        f"plot edges: {graph.number_of_edges():,}"
    )

    if graph.number_of_edges() == 0:
        print(
            "[warning] No saved community pairs matched the selected IDs. "
            "Check the JSON IDs and membership mapping."
        )
        return

    # Layout only the small community graph.
    pos = nx.spring_layout(
        graph,
        seed=2222,
        weight="weight",
        iterations=150,
    )

    max_size = max(sizes[cid] for cid in graph.nodes())
    node_sizes = [
        150 + 1000 * math.sqrt(graph.nodes[cid]["size"] / max_size)
        for cid in graph.nodes()
    ]

    max_weight = max(
        data["weight"] for _, _, data in graph.edges(data=True)
    )

    def width(data):
        return 0.5 + 2.0 * (
            math.log1p(data["weight"]) / math.log1p(max_weight)
        )

    normal_edges = [
        (u, v) for u, v, d in graph.edges(data=True)
        if d["bridge_count"] == 0
    ]
    bridge_edges = [
        (u, v) for u, v, d in graph.edges(data=True)
        if d["bridge_count"] > 0
    ]

    fig, ax = plt.subplots(figsize=(15, 11))

    nx.draw_networkx_edges(
        graph, pos,
        edgelist=normal_edges,
        width=[width(graph[u][v]) for u, v in normal_edges],
        edge_color="gray",
        alpha=0.55,
        ax=ax,
    )

    nx.draw_networkx_edges(
        graph, pos,
        edgelist=bridge_edges,
        width=[width(graph[u][v]) + 1 for u, v in bridge_edges],
        edge_color="red",
        alpha=0.95,
        ax=ax,
    )

    nx.draw_networkx_nodes(
        graph, pos,
        node_size=node_sizes,
        node_color=[graph.nodes[cid]["size"] for cid in graph.nodes()],
        cmap=plt.cm.viridis,
        edgecolors="black",
        linewidths=0.6,
        ax=ax,
    )

    labels = {
        cid: f"C{cid}\n{graph.nodes[cid]['size']:,} users"
        for cid in graph.nodes()
    }
    nx.draw_networkx_labels(
        graph, pos, labels=labels, font_size=8, ax=ax
    )

    ax.set_title(
        f"Leiden community network: largest {len(graph)} communities\n"
        "Node size = number of users | Edge width = original edges "
        "| Red = structural bridge edge(s)"
    )
    ax.axis("off")
    fig.tight_layout()

    out.mkdir(parents=True, exist_ok=True)
    fig.savefig(
        out / "18_leiden_community_network.png",
        dpi=220,
        bbox_inches="tight",
    )
    fig.savefig(
        out / "18_leiden_community_network.pdf",
        bbox_inches="tight",
    )
    plt.close(fig)

    print(f"[community plot] Saved PNG and PDF to {out}")


def write_report_summary(metrics: dict[str, Any], comm: dict[str, Any], hits: dict[str, Any], out: Path) -> None:
    leiden = comm.get("leiden") or {}
    clique = comm.get("cliques") or {}
    bridge = comm.get("bridges") or {}
    rows = [
        ("Nodes", metrics.get("numNodes", "")),
        ("Directed edges", metrics.get("numEdges", "")),
        ("Average clustering", metrics.get("averageClustering", "")),
        ("Transitivity", metrics.get("transitivity", "")),
        ("Directed density", metrics.get("density", "")),
        ("Weakly connected components", metrics.get("numWeaklyConnectedComponents", "")),
        ("Strongly connected components", metrics.get("numStronglyConnectedComponents", "")),
        ("Approximate diameter of largest SCC", metrics.get("diameterLargestSCC", "")),
        ("Leiden communities", leiden.get("numCommunities", "")),
        ("Leiden modularity", leiden.get("modularity", "")),
        ("Leiden singleton communities", leiden.get("numSingletons", "")),
        ("Largest maximal clique size", clique.get("largestCliqueSize", "")),
        ("Number of maximal cliques (size >= configured minimum)", clique.get("numMaximalCliques", "")),
        ("Articulation points", bridge.get("numArticulationPoints", "")),
        ("Bridge edges", bridge.get("numBridgeEdges", "")),
        ("Cross-community edges", bridge.get("crossCommunityEdges", "")),
        ("Cross-community edge share", bridge.get("crossCommunityEdgeShare", "")),
        ("Degree assortativity", (comm.get("homophily") or {}).get("degreeAssortivity", "")),
        ("Top HITS hub available", bool(hits.get("hubs"))),
        ("Top HITS authority available", bool(hits.get("authorities"))),
    ]
    write_csv(out / "report_summary.csv", ["metric", "value"], [[k, v] for k, v in rows])


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data-dir", type=Path, default=Path("."),
                        help="Folder containing the JSON input files (default: current directory)")
    parser.add_argument("--out-dir", type=Path, default=Path("report_figures"),
                        help="Output folder (default: report_figures)")
    parser.add_argument("--top-n", type=int, default=20,
                        help="Number of nodes in top-node plots (default: 20)")
    args = parser.parse_args()
    args.out_dir.mkdir(parents=True, exist_ok=True)

    metrics = load_json(args.data_dir / "metrics.json")
    comm = load_json(args.data_dir / "commMetrics.json")
    hits = load_json(args.data_dir / "hitsMetrics.json")

    if not (metrics or comm or hits):
        raise SystemExit("No input JSON files found. Check --data-dir.")

    plt.rcParams.update({
        "figure.dpi": 120,
        "savefig.dpi": 220,
        "font.size": 10,
        "axes.titlesize": 12,
        "axes.labelsize": 10,
        "legend.fontsize": 9,
        "pdf.fonttype": 42,
        "ps.fonttype": 42,
    })

    # plot_degree_distributions(metrics, args.out_dir)
    # plot_network_summary(metrics, comm, args.out_dir)
    # plot_component_sizes(metrics, args.out_dir)
